# Drives the MCP endpoint the way a client does (generated by maquina:mcp).
#
#   mcp_post({method: "tools/call", params: {name: "whoami", arguments: {}}}, token: oauth_token_for(user))
#   response.parsed_body.dig("result", "structuredContent")
#
# mcp_post fills in what every 2026-07-28 request carries, from the payload:
# jsonrpc and id, params._meta with the protocol version
# (params._meta["io.modelcontextprotocol/protocolVersion"]) and client
# capabilities, and the MCP-Protocol-Version, Mcp-Method and Mcp-Name headers.
# Anything the payload already sets is kept, and `headers:` overrides a
# header (nil leaves it out), so a test can send a mismatch on purpose.
#
# With a feature flag (Mcp::FLAG), every test starts with the flag on; call
# mcp_flag(false) to test it off. Both go through the ENV fallback in
# Mcp.enabled_for?: if the app moves its flag elsewhere, change mcp_flag.
#
# The admin-only tools are for people on the backstage list
# (User#backstage_access?). Every test starts with the mcp_admin fixture on it,
# through config.x.backstage_emails, which User.backstage_emails reads first.
module McpTestHelper
  MCP_PROTOCOL_VERSION_META = "io.modelcontextprotocol/protocolVersion"
  MCP_CLIENT_CAPABILITIES_META = "io.modelcontextprotocol/clientCapabilities"
  # Integration tests run on www.example.com, so tokens are issued for it.
  MCP_RESOURCE = "http://www.example.com/mcp"
  MCP_BACKSTAGE_EMAILS = %w[mcp-admin@example.com].freeze

  def self.included(base)
    base.setup do
      mcp_flag(true)
      @backstage_emails_before = Rails.configuration.x.backstage_emails
      Rails.configuration.x.backstage_emails = MCP_BACKSTAGE_EMAILS.dup
    end
    base.teardown do
      restore_mcp_flag
      Rails.configuration.x.backstage_emails = @backstage_emails_before
    end
  end

  def mcp_post(payload, token: nil, headers: {})
    body = mcp_payload(payload)
    params = body["params"]
    request_headers = {
      "Content-Type" => "application/json",
      "Authorization" => ("Bearer #{token}" if token),
      "MCP-Protocol-Version" => params.dig("_meta", MCP_PROTOCOL_VERSION_META),
      "Mcp-Method" => body["method"],
      "Mcp-Name" => (params["name"] if body["method"] == "tools/call")
    }.merge(headers).compact

    post mcp_path, params: ::JSON.generate(body), headers: request_headers
  end

  # A raw access token for the MCP Inspector fixture client, for this server.
  def oauth_token_for(user, scope: "read")
    AccessToken.issue!(user: user, client: oauth_clients(:inspector), scope: scope, resource: MCP_RESOURCE).first
  end

  def mcp_flag(enabled)
    return unless Mcp::FLAG

    key = Mcp::FLAG.to_s.upcase
    @mcp_flag_before = ENV[key] unless defined?(@mcp_flag_before)
    ENV[key] = enabled.to_s
  end

  private

  def restore_mcp_flag
    return unless Mcp::FLAG && defined?(@mcp_flag_before)

    ENV[Mcp::FLAG.to_s.upcase] = @mcp_flag_before
  end

  def mcp_payload(payload)
    body = payload.deep_stringify_keys
    body["jsonrpc"] = "2.0" unless body.key?("jsonrpc")
    body["id"] = 1 unless body.key?("id")
    body["params"] = {} unless body["params"].is_a?(Hash)
    body["params"]["_meta"] ||= {
      MCP_PROTOCOL_VERSION_META => Mcp::PROTOCOL_VERSION,
      MCP_CLIENT_CAPABILITIES_META => {}
    }
    body
  end
end

ActiveSupport.on_load(:active_support_test_case) do
  include McpTestHelper
end
